    nums = list(map(int, re.findall(r'\d+', text)))
    ops = re.findall(r'[+\-*/]', text)
    return {'numbers': nums, 'operators': ops}
# 分步输出加法推导文本并计算结果
def cot_reasoning(problem):
    parsed = parse_math_problem(problem)
    steps = []
    if '+' in problem:
        total = sum(parsed['numbers'])
        for n in parsed['numbers']:
            steps.append(f'当前数字: {n}')
        steps.append(f'相加得: {total}')
    return {'steps': steps, 'answer': total if '+' in problem else None}
# 核对推理字典 answer 字段是否符合预期答案
def verify_answer(steps, expected):
    return steps.get('answer') == expected if isinstance(steps, dict) else False

