# 包装名称、可执行体与 schema 描述
def register_tool(name, func, schema):
    return {'name': name, 'func': func, 'schema': schema}
# 定位起止标签并用 json 解析工具调用载体
def parse_tool_call(response):
    if '<tool>' in response:
        start = response.index('<tool>')+6
        end = response.index('</tool>', start)
        return json.loads(response[start:end])
    return None
# 匹配注册名称并以关键字参数触发工具
def execute_tool(tool_name, args, tools):
    for t in tools:
        if t['name'] == tool_name:
            return t['func'](**args)
    return f'unknown tool: {tool_name}'

# 【算法思路】执行带参数 JSON Schema 类型（string/number/boolean/array/object）校验及失败自动重试的函数调用。
import json

# 读取函数名与参数从注册表分派执行
def execute_function_call(func_call, registry):
    name = func_call.get("name") if isinstance(func_call, dict) else func_call["name"]
    args = func_call.get("arguments", {}) if isinstance(func_call, dict) else func_call["arguments"]
    fn = registry.get(name)
    if not fn:
        return f"unknown function: {name}"
    return fn(**args)

# 按 JSON Schema 类型映射严格检验字段类型与必填约束
def validate_arguments(args, schema):
    type_map = {
        "string": (str,),
        "number": (int, float),
        "integer": (int,),
        "boolean": (bool,),
        "array": (list,),
        "object": (dict,),
    }
    for key, props in schema.get("properties", {}).items():
        if key in args:
            expected = props.get("type")
            val = args[key]
            if expected == "boolean":
                if not isinstance(val, bool):
                    return False
            elif expected in ("number", "integer"):
                if isinstance(val, bool) or not isinstance(val, type_map[expected]):
                    return False
            elif expected in type_map:
                if not isinstance(val, type_map[expected]):
                    return False
            elif type(val).__name__ != expected:
                return False
        elif props.get("required", False):
            return False
    return True

# 按最大重试次数捕获异常直至成功或上抛末次异常
def call_with_retry(func, args, max_retries=3):
    last = None
    for _ in range(max_retries):
        try:
            return func(**args)
        except Exception as e:
            last = e
    raise last

